-- KICD 2024 Grade 4 English structure: 13 themes, 4 strands, 52 theme/skill planning units.
-- VibeSchool-original independently authored guidance: 156 outcomes; 150 estimated annual teaching lessons.
-- The KICD design allocates five English periods weekly, not this migration's term/week dates.
-- authorization-test: public.grade4_english_reader_bindings
-- No existing Grade 4 legacy row, teacher Scheme, lesson plan or timetable is modified.
begin;
create table if not exists public.grade4_english_reader_bindings (
 source_ref text primary key check(source_ref like 'VS-CUR-G04-EN-2026#%'),
 sub_strand_id uuid not null unique references public.cbc_strands(id) on delete restrict,
 source_url text not null,
 source_version text not null,
 key_inquiry_questions text[] not null default '{}',
 suggested_experiences text[] not null default '{}',
 status text not null default 'active' check(status in ('active','archived')),
 created_at timestamptz not null default now()
);
alter table public.grade4_english_reader_bindings enable row level security;
revoke all on public.grade4_english_reader_bindings from public,anon,authenticated;
grant select on public.grade4_english_reader_bindings to authenticated;
drop policy if exists grade4_english_bindings_read on public.grade4_english_reader_bindings;
create policy grade4_english_bindings_read on public.grade4_english_reader_bindings
 for select to authenticated using(status='active');

create temporary table _vs_g4_english_catalog(source_ref text primary key,unit jsonb not null) on commit drop;
insert into _vs_g4_english_catalog(source_ref,unit)
select 'VS-CUR-G04-EN-2026#'||(unit->>'id'),unit
from jsonb_array_elements($vs_g4_en$[{"id":"01-LS","theme":1,"themeTitle":"The Family","sourcePage":1,"strand":"Listening and Speaking","title":"The Family: Pronunciation and Vocabulary — Listening Comprehension","focus":"Pronunciation and Vocabulary — Listening Comprehension","lessons":2,"outcomes":["Listen attentively to a conversation about helping at home and report two accurate details using the topic vocabulary.","Practise pronunciation and vocabulary: listening comprehension in a short paired exchange, checking pronunciation, clarity and respectful turn-taking.","Respond orally to a follow-up question about family roles, kind choices and everyday routines using an appropriate tone and complete thought."],"inquiry":["How does careful listening improve a conversation about the family?","What helps a speaker make pronunciation and vocabulary: listening comprehension clear to a listener?"],"experiences":["Hear and retell a conversation about helping at home; compare what different listeners remembered.","Rehearse a 30-second dialogue using the target sounds or language pattern, and exchange specific peer feedback."],"resources":"Teacher-recorded spoken model, vocabulary picture cards and two-person speaking prompts.","assessment":"Short listening recall, pronunciation observation and partner-dialogue checklist.","competencies":"Communication and collaboration; critical thinking; creativity; self-efficacy; digital literacy where safe and available."},{"id":"01-RD","theme":1,"themeTitle":"The Family","sourcePage":1,"strand":"Reading","title":"The Family: Extensive Reading — Reference Materials","focus":"Extensive Reading — Reference Materials","lessons":2,"outcomes":["Read a short account of family responsibilities with attention to the focus: extensive reading: reference materials.","Locate two details in the text and explain an inference in a complete sentence.","Use context, rereading or an age-appropriate reference to explain unfamiliar words linked to the fami