ry entry and discuss what makes it useful.","Draft an original response, peer-check purpose and conventions, and improve the final copy."],"resources":"Original writing model, planning frame, notebooks and self-editing checklist.","assessment":"Completed writing product with purpose, organisation, language accuracy and evidence of revision.","competencies":"Communication and collaboration; critical thinking; creativity; self-efficacy; digital literacy where safe and available."}]$vs_g4_en$::jsonb) unit;

do $preflight$
begin
 if (select count(*) from _vs_g4_english_catalog)<>52
   or (select count(distinct unit->>'theme') from _vs_g4_english_catalog)<>13
   or (select count(distinct unit->>'strand') from _vs_g4_english_catalog)<>4
   or (select sum((unit->>'lessons')::int) from _vs_g4_english_catalog)<>150
   or (select sum(jsonb_array_length(unit->'outcomes')) from _vs_g4_english_catalog)<>156
 then raise exception 'GRADE4_ENGLISH_INDEX_UNITS_INCOMPLETE'; end if;
 if (select count(*) from public.subjects
     where lower(name)='english' and school_id is null and global_subject_id is null)<>1
 then raise exception 'GRADE4_ENGLISH_GLOBAL_SUBJECT_REQUIRED'; end if;
 if exists(select 1 from _vs_g4_english_catalog t
   join public.subjects sub on lower(sub.name)='english' and sub.school_id is null and sub.global_subject_id is null
   join public.cbc_strands s on s.subject_id=sub.id and s.grade='Grade 4'
    and s.name=t.unit->>'strand' and s.sub_strand=t.unit->>'title'
   where s.source_ref is not null and s.source_ref<>t.source_ref)
 then raise exception 'GRADE4_ENGLISH_EXISTING_SOURCE_CONFLICT'; end if;
end;$preflight$;

insert into public.cbc_strands
 (subject_id,grade,name,sub_strand,strand_order,sub_strand_order,
 key_inquiry_questions,suggested_experiences,source_ref)
select sub.id,'Grade 4',t.unit->>'strand',t.unit->>'title',
 case t.unit->>'strand'
   when 'Listening and Speaking' then 1 when 'Reading' then 2
   when 'Grammar in Use' then 3 else 4 end,
 (t.unit->>'theme')::integer,
 array(select jsonb_array_elements_text(t.unit->'inquiry')),
 array(select jsonb_array_elements_text(t.unit->'experiences')),
 t.source_ref
from _vs_g4_english_catalog t
join public.subjects sub on lower(sub.name)='english' and sub.school_id is null and sub.global_subject_id is null
on conflict(subject_id,grade,name,sub_strand) do nothing;

insert into public.grade4_english_reader_bindings
 (source_ref,sub_strand_id,source_url,source_version,key_inquiry_questions,suggested_experiences)
select t.source_ref,s.id,'https://kicd.ac.ke/wp-content/uploads/2024/02/GRADE.4.ENGLISH.LANGUAGE.pdf','KICD revised 2024',
 array(select jsonb_array_elements_text(t.unit->'inquiry')),
 array(select jsonb_array_elements_text(t.unit->'experiences'))
from _vs_g4_english_catalog t
join public.subjects sub on lower(sub.name)='english' and sub.school_id is null and sub.global_subject_id is null
join public.cbc_strands s on s.subject_id=sub.id and s.grade='Grade 4'
 and s.name=t.unit->>'strand' and s.sub_strand=t.unit->>'title'
on conflict(source_ref) do nothing;

insert into public.curriculum_unit_guidance
 (sub_strand_id,suggested_lessons,learning_resources,assessment_methods,competencies,safety_notes,content_status)
select b.sub_strand_id,(t.unit->>'lessons')::int,
 t.unit->>'resources',t.unit->>'assessment',t.unit->>'competencies',
 'Use age-appropriate original texts; protect learner privacy, especially around health, personal information and online activities.','active'
from _vs_g4_english_catalog t
join public.grade4_english_reader_bindings b on b.source_ref=t.source_ref
on conflict(sub_strand_id) do nothing;

insert into public.curriculum_learning_outcomes
 (sub_strand_id,outcome_text,outcome_code,source_type,source_ref,status)
select b.sub_strand_id,o.text,
 'VS-G4-EN-'||(t.unit->>'id')||'-'||lpad(o.ordinality::text,2,'0'),
 'creator_claimed',t.source_ref||'/'||o.ordinality,'active'
from _vs_g4_english_catalog t
join public.grade4_english_reader_bindings b on b.source_ref=t.source_ref
cross join lateral jsonb_array_elements_text(t.unit->'outcomes')
 with ordinality as o(text,ordinality)
where not exists(select 1 from public.curriculum_learning_outcomes v
 where v.source_ref=t.source_ref||'/'||o.ordinality);
drop policy if exists grade4_english_original_outcomes_read on public.curriculum_learning_outcomes;
create policy grade4_english_original_outcomes_read on public.curriculum_learning_outcomes
 for select to authenticated using(
  status='active' and source_type='creator_claimed' and created_by is null
  and source_ref like 'VS-CUR-G04-EN-2026#%');
drop policy if exists grade4_english_guidance_read on public.curriculum_unit_guidance;
create policy grade4_english_guidance_read on public.curriculum_unit_guidance
 for select to authenticated using(
  content_status='active' and exists(select 1 from public.grade4_english_reader_bindings b
   where b.sub_strand_id=curriculum_unit_guidance.sub_strand_id and b.status='active'));

do $verify$
begin
 if (select count(*) from public.grade4_english_reader_bindings
       where source_ref like 'VS-CUR-G04-EN-2026#%' and status='active')<>52
  or (select count(*) from public.curriculum_learning_outcomes
       where source_ref like 'VS-CUR-G04-EN-2026#%' and status='active')<>156
  or (select coalesce(sum(g.suggested_lessons),0)
       from public.grade4_english_reader_bindings b
       join public.curriculum_unit_guidance g on g.sub_strand_id=b.sub_strand_id
       where b.status='active' and g.content_status='active')<>150
 then raise exception 'GRADE4_ENGLISH_PERSISTENCE_INCOMPLETE'; end if;
end;$verify$;

-- Extend the existing canonical security-invoker Scheme save RPC without rewriting
-- the previously registered Grade 1, 4 Mathematics, 6 or 8 authorization checks.
do $patch$
declare
 definition text;
 old_gate text := $target$  if not found then raise exception 'SCHEME_CURRICULUM_SUBSTRAND_NOT_FOUND'; end if;$target$;
 new_gate text := $replacement$  if not found then
    select * into v_unit from public.cbc_strands s
    where s.id=p_sub_strand_id and s.grade='Grade 4'
      and exists(select 1 from public.grade4_english_reader_bindings b
                 where b.sub_strand_id=s.id and b.status='active');
  end if;
  if not found then raise exception 'SCHEME_CURRICULUM_SUBSTRAND_NOT_FOUND'; end if;$replacement$;
 old_lookup text := $target$  if v_reader_ref is null then
    v_reader_ref:=v_unit.source_ref;$target$;
 new_lookup text := $replacement$  if v_reader_ref is null then
    select b.source_ref,b.key_inquiry_questions,b.suggested_experiences
      into v_reader_ref,v_reader_inquiry,v_reader_experiences
    from public.grade4_english_reader_bindings b
    where b.sub_strand_id=v_unit.id and b.status='active';
  end if;
  if v_reader_ref is null then
    v_reader_ref:=v_unit.source_ref;$replacement$;
begin
 definition:=pg_get_functiondef('public.commit_mapped_scheme_lesson(uuid,uuid,uuid,integer,uuid,uuid[])'::regprocedure);
 if definition ilike '%security definer%' then raise exception 'SCHEME_INVOKER_AUTHORITY_REQUIRED'; end if;
 if position(old_gate in definition)=0 or position(old_lookup in definition)=0
 then raise exception 'SCHEME_RPC_VERSION_INCOMPATIBLE_WITH_GRADE4_ENGLISH'; end if;
 definition:=replace(replace(definition,old_gate,new_gate),old_lookup,new_lookup);
 execute definition;
end;$patch$;
revoke all on function public.commit_mapped_scheme_lesson(uuid,uuid,uuid,integer,uuid,uuid[]) from public,anon;
grant execute on function public.commit_mapped_scheme_lesson(uuid,uuid,uuid,integer,uuid,uuid[]) to authenticated;
commit;
